import React from "react";
import { FaBolt, FaUserGraduate, FaLeaf } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects">

      {/* HEADER */}
      <div className="header">
        <h1>Project Systems</h1>
        <p>Structured builds mapped as an engineering flow of real-world solutions</p>
      </div>

      {/* CENTRAL FLOW LINE */}
      <div className="timeline">

        {/* COGNI FLOW (now included properly) */}
        <div className="node">
          <div className="dot"></div>
          <div className="card">
            <h2>Cogni Flow</h2>
            <p>
              A structured workflow-based system designed to simplify task flow,
              improve clarity, and enhance productivity through logical UI design.
            </p>
            <span>Tech: HTML • CSS • JavaScript</span>
          </div>
        </div>

        {/* ENERGY PULSE */}
        <div className="node">
          <div className="dot"></div>
          <div className="card">
            <h2>EnergyPulse</h2>
            <p>
              AI-powered smart home dashboard frontend displaying real-time
              biometric and energy optimization data with responsive UI system.
            </p>
            <span>Tech: React.js</span>
          </div>
        </div>

        {/* STUDENT PORTAL */}
        <div className="node">
          <div className="dot"></div>
          <div className="card">
            <h2>Student Portal Management</h2>
            <p>
              Full-stack academic management system with structured backend APIs
              using Java Spring Boot and interactive frontend for record handling.
            </p>
            <span>Tech: Spring Boot • MySQL • Web Stack</span>
          </div>
        </div>

        {/* FARM2FORK */}
        <div className="node">
          <div className="dot"></div>
          <div className="card">
            <h2>Farm2Fork</h2>
            <p>
              Responsive digital marketplace connecting farmers and consumers
              with smooth product listing and intuitive UI flow system.
            </p>
            <span>Tech: HTML • CSS • JavaScript</span>
          </div>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .projects {
          min-height: 100vh;
          padding: 40px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 60px;
        }

        .header h1 {
          font-size: 42px;
          color: #e2e8f0;
        }

        .header p {
          color: #94a3b8;
          margin-top: 8px;
        }

        /* TIMELINE SYSTEM */
        .timeline {
          position: relative;
          display: flex;
          flex-direction: column;
          gap: 40px;
          padding-left: 30px;
        }

        /* vertical glowing line */
        .timeline::before {
          content: "";
          position: absolute;
          left: 10px;
          top: 0;
          width: 2px;
          height: 100%;
          background: rgba(56,189,248,0.25);
          box-shadow: 0 0 10px rgba(56,189,248,0.2);
        }

        .node {
          display: flex;
          gap: 20px;
          position: relative;
        }

        /* glowing dot */
        .dot {
          width: 14px;
          height: 14px;
          border-radius: 50%;
          background: #38BDF8;
          box-shadow: 0 0 12px #38BDF8;
          position: relative;
          top: 18px;
        }

        /* CARD */
        .card {
          background: rgba(255,255,255,0.03);
          border: 1px solid rgba(56,189,248,0.15);
          padding: 20px;
          border-radius: 14px;
          width: 100%;
          transition: 0.3s;
        }

        .card:hover {
          transform: translateX(8px);
          border-color: #38BDF8;
          box-shadow: 0 0 20px rgba(56,189,248,0.15);
        }

        .card h2 {
          color: #38BDF8;
          margin-bottom: 8px;
        }

        .card p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .card span {
          display: inline-block;
          margin-top: 10px;
          color: #94a3b8;
          font-size: 13px;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .timeline {
            padding-left: 20px;
          }

          .node {
            flex-direction: column;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
